Translate the following MS C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original MS C++ code you have to translate:
<original_code>
#include <iostream>
#include <algorithm>
#include <cmath>
using namespace std;

long long compute_gcd(int a, int b) {
    while (b != 0) {
        int temp = a % b;
        a = b;
        b = temp;
    }
    return a;
}

long long compute_lcm(int a, int b) {
    return (long long)a * b / compute_gcd(a, b);
}

double measure_difference(int x1, int y1, int x2, int y2) {
    long long l = compute_lcm(y1, y2);
    long long diff = abs(l / y1 * x1 - l / y2 * x2);
    return (double)diff / l;
}

int main() {
    int x, y, n;
    cin >> x >> y >> n;
    double min_diff = 1e15;
    int min_b = 1;
    double target_ratio = (double)x / y;

    for (int i = 1; i <= n; ++i) {
        int left = 1, right = 1000000;
        while (right - left > 1) {
            int mid = (left + right) / 2;
            double ratio = (double)mid / i;
            if (ratio < target_ratio)
                left = mid;
            else
                right = mid;
        }
        int candidate = left;
        double diff_left = measure_difference(candidate, i, x, y);
        double diff_right = measure_difference(right, i, x, y);
        int chosen = (diff_left < diff_right) ? candidate : right;
        double current_diff = measure_difference(chosen, i, x, y);
        if (current_diff < min_diff) {
            min_diff = current_diff;
            min_b = i;
        }
    }
    cout << min_b << "/" << n;
    return 0;
}
